import{_ as t,o as n,c as a,ak as i}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse(`{"title":"GDD comparison and proposed minimum version","description":"October 24, 2026. Review draft for Sherwin's scope decision and Sean's documentation handoff; not an adopted replacement GDD. Christian validates technical effort. Community b","frontmatter":{"title":"GDD comparison and proposed minimum version","description":"October 24, 2026. Review draft for Sherwin's scope decision and Sean's documentation handoff; not an adopted replacement GDD. Christian validates technical effort. Community b","source":"docs/archive/pre-lesson-collection-2026-11-11/planning/gdd-v2-simplification-review.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/planning/gdd-v2-simplification-review.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/planning/gdd-v2-simplification-review.md"}`),r={name:"content/docs/archive/pre-lesson-collection-2026-11-11/planning/gdd-v2-simplification-review.md"};function o(s,e,d,c,l,h){return n(),a("div",null,[...e[0]||(e[0]=[i('<div><h1 id="gdd-comparison-and-proposed-minimum-version">GDD comparison and proposed minimum version<a class="header-anchor" href="#gdd-comparison-and-proposed-minimum-version" aria-label="Link to this section">​</a></h1><p>October 24, 2026. Review draft for Sherwin&#39;s scope decision and Sean&#39;s documentation handoff; <strong>not an adopted replacement GDD</strong>. Christian validates technical effort. <strong>Community beta: November 10, 2026. Pre-final: November 21, 2026.</strong></p><h2 id="recommendation">Recommendation<a class="header-anchor" href="#recommendation" aria-label="Link to this section">​</a></h2><p><strong>Reduce the mechanics while retaining the three subjects.</strong> Keep V2&#39;s compact exploration, guides, narrative continuity and visible restoration. Teach through one reusable illustrated scenario-and-choice interaction. Defer the working economy, inventory, transaction system, ledger reconstruction engine and trained classifier unless a confirmed requirement prevents that reduction.</p><p>The proposed minimum is a guided 3D learning adventure with three short chapters, six scenario encounters, explanatory retries, one fresh understanding check per chapter, and SQLite progress saves. The six encounters are content packages using the same interaction, not six custom mini-games. Each encounter can contain several brief decisions.</p><p>This proposal changes the depth of implementation: all twelve existing Web3/blockchain concepts remain in the introductory coverage, but individual functioning simulations move to later development. AI teaching becomes required; a trainable AI implementation is a separate decision. This tradeoff requires explicit agreement because the adopted V2 currently promises hands-on systems and makes AI stretch.</p><h2 id="what-was-reviewed">What was reviewed<a class="header-anchor" href="#what-was-reviewed" aria-label="Link to this section">​</a></h2><ul><li><a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/game-design.html">V1: October 22 mini-game-first GDD</a>, the immediate predecessor identified by the GDD directory.</li><li><a href="/Chainy-Docs/content/docs/game-design.html">V2: adopted October 23 gameplay-first GDD</a>, particularly sections 3, 5 and 7.</li><li><a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/game-design.html">October 8 bounded-learning GDD</a>, as an additional historical comparison because “first version” could refer to that illustrated edition.</li><li><a href="/Chainy-Docs/content/docs/project-baseline.html">Current baseline</a>, <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">delivery plan</a>, <a href="/Chainy-Docs/content/docs/technical-design.html">technical design</a>, <a href="/Chainy-Docs/content/docs/planning/quest-curriculum.html">curriculum map</a> and <a href="/Chainy-Docs/content/docs/gdd-template-editions.html">GDD edition directory</a>.</li><li>The requested primary content source: <a href="/Chainy-Docs/content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.html">Web3 Young Learners Encyclopedia — A–Z contents</a>.</li></ul><p>The encyclopedia Markdown contains chapter titles, page locators and concise summaries, not the complete chapter text. It is useful for choosing coverage and tracing sources; it does not supply a finished script, validated assessment, or an AI curriculum. This review did not inspect the underlying encyclopedia PDF.</p><h2 id="comparison-and-findings">Comparison and findings<a class="header-anchor" href="#comparison-and-findings" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Area</th><th>V1</th><th>V2</th><th>Recommendation</th></tr></thead><tbody><tr><td>Core loop</td><td>Explore, dialogue, Quiz/Wordle/BlockMatch, result, save</td><td>Explore, quest action, persistent consequence, restoration, save</td><td>Keep exploration and meaningful scenarios; reuse the choice screen throughout</td></tr><tr><td>Educational strength</td><td>Familiar formats, but spelling/matching can become disconnected from understanding</td><td>Decisions have context and consequences; the same purchase links subjects</td><td>Preserve that context with an authored receipt and examples</td></tr><tr><td>Educational gap</td><td>Exact rules, learning relations and completion criteria remain unresolved</td><td>AI is optional in the beta despite the three-subject mission</td><td>Include a small AI chapter from the start</td></tr><tr><td>Code scope</td><td>Three mini-game rule sets, screens, result handling and saves</td><td>Quest states, pickups, rewards, economy, ownership, purchases, records, repair and optional training</td><td>One lesson sequence, response/feedback, completion and persistence</td></tr><tr><td>Dependencies</td><td>Mini-games need separate rules and integration</td><td>Web3 state feeds Blockchain; AI waits for their acceptance</td><td>Chapters share presentation and content, without sharing a mutable economy</td></tr><tr><td>Persistence</td><td>Local profiles and activity results</td><td>Also balances, inventory, ledger, quest and restoration state that must agree</td><td>Save learning progress; derive visual restoration from saved completion</td></tr><tr><td>Deadline risk</td><td>Lower system breadth, but unfinished Wordle/BlockMatch are still substantial work</td><td>Even the reduced core has several new interacting systems</td><td>Do not restore all three V1 mini-games as the fallback</td></tr></tbody></table><p>Christian&#39;s concern is supported by the specification. The economic simulation is already in CORE: W02 rewards 12 coins; W03 spends 8 plus a 1-coin fee; W04 checks ownership and equipment; B01 reads that saved purchase. Removing only the later exchange does not remove the implementation burden. Cancellation, duplicate taps, repeat rewards, interrupted saves and recovery all need consistent behavior.</p><p>V2&#39;s own estimate is <strong>95–153 focused technical hours for its core</strong>, plus <strong>20–35 for optional AI</strong>, under favorable reuse assumptions. These are planning estimates, not measured productivity. UI, art and instructional copy have separate workloads. The October 24 developer concern is new evidence against treating the October 23 conditional plan as a commitment.</p><p>The October 8 version already offered bounded lessons without an economy. Its strongest reusable ideas are prediction, comparison, feedback and retry. Reinstating that entire design would still add bespoke ordering, copy comparison, a classifier and a grid-agent activity; it is not automatically the cheapest fallback either.</p><h2 id="proposed-minimum-gdd">Proposed minimum GDD<a class="header-anchor" href="#proposed-minimum-gdd" aria-label="Link to this section">​</a></h2><p><strong>Purpose:</strong> teach introductory Web3, blockchain and AI concepts to ages 12–17 through short decisions in a familiar offline 3D world.</p><p><strong>Presentation:</strong> keep the existing Explorer, fixed isometric view, live-world dialogue overlay, and Sean/ Matthew/Lee guide identities. Use the smallest existing scenes or a shared compact layout with three themed areas, whichever Christian confirms requires less work. Three subject chapters do not require three newly built islands.</p><p><strong>Story:</strong> the Explorer helps the guides reopen three learning/service stations by checking their instructions, records and advice. A lamp, beacon or desk indicator changes after each completed chapter. This visual change acknowledges progress; it does not claim that answering a quiz executes a real smart contract or repairs a real blockchain.</p><p><strong>Repeated play loop:</strong> walk to a visible guide → inspect one short example → choose a response → see the consequence and explanation → retry or continue → save progress → show the next objective.</p><p>Use the same dialogue/choice UI for comparing a receipt, judging a suspicious message and checking an AI prediction. No drag-and-drop board, free-text chatbot, trading screen or separate training interface is needed for this proposal.</p><h3 id="six-scenario-encounters">Six scenario encounters<a class="header-anchor" href="#six-scenario-encounters" aria-label="Link to this section">​</a></h3><table><thead><tr><th>ID</th><th>Scenario and learner action</th><th>Feedback and learning evidence</th></tr></thead><tbody><tr><td>F-W1</td><td><strong>Access and safety.</strong> Meet Sean; inspect a fictional account diagram and a suspicious message. Choose shareable receiving information, protect the private key/backup, and identify the wallet&#39;s role. Introduce who controls information and what shared control means.</td><td>Explain why an address differs from a secret and why wallet access differs from the ledger record. No real secrets are entered.</td></tr><tr><td>F-W2</td><td><strong>Read the digital receipt.</strong> Inspect a fixed example for Lantern #014: price 8 and fee 1. In short successive prompts, distinguish cryptocurrency from fiat, fee from price, a unique ownership record from interchangeable tokens, exchange from purchase, and a programmed condition from a human promise.</td><td>Explain each choice with the displayed evidence. All amounts and examples are authored lesson content; no player balance, inventory or trade changes.</td></tr><tr><td>F-B1</td><td><strong>Find the changed record.</strong> Matthew shows a verified reference receipt with price 8 and a local copy with price 6. Choose the mismatch and the valid next block from two illustrated candidates with previous-reference labels.</td><td>Reference labels determine the correct link, not color. Explain that the comparison detects disagreement with the supplied reference; it does not prove a real event occurred.</td></tr><tr><td>F-B2</td><td><strong>Who keeps and checks records?</strong> Inspect a diagram of logical node copies and two contrasting descriptions of proof of work and proof of stake. Distinguish storing/checking records, proposing blocks and agreement under network rules; recognize an unresolved disagreement.</td><td>Explain that copies alone do not establish truth and a learner&#39;s approval is not network consensus. No network, mining loop or replica synchronization engine.</td></tr><tr><td>F-A1</td><td><strong>Examples and predictions.</strong> Lee shows labelled parcel examples and an authored prediction on a different parcel. Identify the training examples, the new test example and a misleading label.</td><td>Explain how examples can affect a model and why checking only remembered examples is insufficient. Label the activity “scripted AI learning example”; no Train button or claim that the app learned from the player.</td></tr><tr><td>F-A2</td><td><strong>Check the helper.</strong> Compare a plausible authored assistant answer with a short supplied record. Select the unsupported claim and choose verify/ask for help before approving an action.</td><td>Explain that plausible output can be wrong and that a suggestion is not authority to act. The response is labelled scripted; no live chatbot or autonomous dispatch.</td></tr></tbody></table><p>F-W2 has the largest content load. Present one decision at a time; splitting its reading across two visits is acceptable if learner trials show overload, without adding a new interaction system. Freeze the approved prompts before expanding optional content.</p><p>Each chapter ends with one fresh application question, different from its worked examples. A wrong response gives a reason and a supported retry. These checks provide limited evidence about the selected objectives, not mastery of every topic. Do not claim learning improvement from completion or a high replay score; the adviser-reviewed evaluation instrument remains separate.</p><h3 id="scope-decisions">Scope decisions<a class="header-anchor" href="#scope-decisions" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Keep now</th><th>Simplify now</th><th>Develop later</th></tr></thead><tbody><tr><td>Offline Android, compact exploration, existing movement/dialogue</td><td>Twenty-quest roadmap → three short chapters/six encounters</td><td>Branching quests, errands, pickups and report-back rewards</td></tr><tr><td>Three subjects and existing guide identities</td><td>Stateful lantern transaction → the same fixed receipt across lessons</td><td>Economy, shop, inventory, equipment and ownership state</td></tr><tr><td>Contextual choices, reasons for errors, replay</td><td>Ledger repair → select/compare supplied evidence</td><td>Editable linked blocks, hashing demonstration and replica synchronization</td></tr><tr><td>SQLite progress and recovery</td><td>Quest log → current objective and chapter completion</td><td>Full journal and four-stage encyclopedia tracking</td></tr><tr><td>Readable phone UI and visible completion feedback</td><td>Glossary → short static definitions for the taught topics</td><td>Full A–Z expansion and additional discovery objects</td></tr><tr><td>AI introduction</td><td>Trained model → clearly labelled authored examples, if accepted</td><td>Actual local classifier, then any assistant/agent simulation</td></tr><tr><td>Existing art and sound where usable</td><td>Restoration → one saved completion-driven visual per chapter</td><td>New landmarks, character types and custom animation sets</td></tr></tbody></table><p>Standalone Wordle and BlockMatch stay deferred unless a working implementation or a school requirement changes the decision. Teacher provisioning, pairing, dashboard, transfer and uploads retain their later-service boundary. These are not dependencies of offline learning.</p><h3 id="minimum-rules-and-acceptance">Minimum rules and acceptance<a class="header-anchor" href="#minimum-rules-and-acceptance" aria-label="Link to this section">​</a></h3><ul><li>One clear objective at a time. Retain the existing Web3 → Blockchain → AI order and allow completed chapters to be revisited; chapter gates depend only on learning completion.</li><li>Advance a decision after the learner has seen the relevant feedback and reached the correct response. Wrong answers cost no resources and never erase progress. Completion means supported activity completion, not independent mastery.</li><li>Save at a supported lesson/encounter boundary. After interruption, restart the unfinished encounter from its introduction and preserve prior completed encounters. Do not promise exact dialogue-line or animation resume.</li><li>Save chapter completion before changing its permanent world indicator or unlocking the next chapter. Reconstruct those visuals from completion on load rather than maintaining a second competing record.</li><li>Store only the local profile identifier, content/version identifiers and progress/results needed by the approved use. If first-answer/hint evidence is needed for evaluation, settle that requirement with Sean before the save contract is frozen. No new analytics dashboard is implied.</li><li>Opening a lesson stops world input. Back, pause and retry return to a usable state. Duplicate taps do not skip prompts or award completion twice.</li><li>On save failure, report the failure, retain the last good checkpoint and offer retry. If profile switching is shipped, keep profiles separate.</li><li>A named Android build must run all three chapters offline, show incorrect-answer feedback, complete and revisit chapters, and preserve the expected checkpoint after force-close/relaunch. Test on actual available phones before asserting compatibility.</li></ul><p>The learning loop and reliable saves remain real implementation work. Reusing a Quiz UI does not by itself provide scenario sequencing, checkpoint behavior or reviewed content.</p><h2 id="encyclopedia-coverage-and-accuracy">Encyclopedia coverage and accuracy<a class="header-anchor" href="#encyclopedia-coverage-and-accuracy" aria-label="Link to this section">​</a></h2><p>The requested file remains the main source for Web3/blockchain topic selection. Its <strong>Exchanges (Know What, Not How)</strong> and <strong>Wallets (Read-Only Awareness)</strong> framing supports awareness-level teaching without a working exchange or economic system. The twelve previously required concepts remain below; their interactive simulations are deferred, not their introductory meanings.</p><table><thead><tr><th>Existing required concept</th><th>Minimum treatment</th><th>Source locator in supplied contents</th></tr></thead><tbody><tr><td>Cryptocurrency</td><td>F-W2: distinguish fictional crypto example from government-issued money</td><td>C/03, PDF p.10; F/06, p.13</td></tr><tr><td>Blockchain</td><td>F-B1: inspect a linked record and compare with a trusted reference</td><td>B/02, p.9; L/12, p.19</td></tr><tr><td>Exchange</td><td>F-W2: identify asset exchange and its purpose; no trading instructions</td><td>E/05, p.12</td></tr><tr><td>Gas fee</td><td>F-W2: distinguish the fee from the item&#39;s price</td><td>G/07, p.14</td></tr><tr><td>Keys</td><td>F-W1: distinguish receiving information from secret signing control</td><td>K/11, p.18</td></tr><tr><td>Mining and validators</td><td>F-B2: compare two mechanisms without treating their roles as identical</td><td>M/13, p.20; P/16, p.23</td></tr><tr><td>NFT</td><td>F-W2: identify a unique token ownership record; uniqueness is not guaranteed value</td><td>N/14, p.21</td></tr><tr><td>Smart contract</td><td>F-W2: predict an outcome from an explicit condition and submitted input</td><td>S/19, p.26</td></tr><tr><td>Token</td><td>F-W2: distinguish interchangeable issued units from a unique item record</td><td>T/20, p.27</td></tr><tr><td>Wallet</td><td>F-W1: identify the interface used to access/manage an account</td><td>W/23, p.30</td></tr><tr><td>Seed phrase</td><td>F-W1: explain backup secrecy and access recovery, without recovery gameplay</td><td>Glossary p.35; W/23, p.30</td></tr><tr><td>Node</td><td>F-B2: identify a participating computer/copy, without simulated networking</td><td>Glossary p.35; D/04, p.11</td></tr></tbody></table><p>Include decentralization, privacy and scam awareness within those scenarios, using D/04, I/09, R/18, U/21, Y/25 and the safety supplements on pp.36–38. Use O/15 (p.22) to distinguish a blockchain record from an ordinary app action. An introduction to Web3 must explain shared control and responsibility, not just cryptocurrency vocabulary. Ethereum&#39;s <a href="https://ethereum.org/web3/">Web3 introduction</a> provides supplementary context; its ecosystem viewpoint is not proof that every Web3 product is decentralized or safe.</p><p>Full A–Z coverage is not automatically a launch requirement. Named assets/services, slang, price movement and zero-knowledge proofs can remain reference or later content unless the school or owner requires them. Do not infer that every encyclopedia letter needs a game system.</p><p>Use precise explanations when simplifying the source:</p><ul><li>A blockchain is resistant to and reveals tampering under its operating assumptions; avoid the absolute “data can never be changed.” A matching local copy or symbolic link alone is not security. See <a href="https://csrc.nist.gov/pubs/ir/8202/final">NIST IR 8202</a>.</li><li>For the account model being taught, the wallet is an interface using keys to access the account; assets do not live inside a picture of a wallet. See <a href="https://ethereum.org/wallets/">Ethereum wallets</a>.</li><li>An ordinary game&#39;s if/then rule is an analogy, not itself a deployed smart contract. A contract needs submitted information to respond to outside events. See <a href="https://ethereum.org/developers/docs/smart-contracts/">Ethereum smart contracts</a>.</li><li>Machine learning uses data to form a model; fixed authored answers in this proposed lesson are a demonstration of ideas, not a model trained by the learner. See <a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml">Google&#39;s introduction to ML</a>.</li><li>Testing should use examples separate from training. If an actual classifier is later implemented, keep training, practice and final cases distinct; a tiny classroom set is not real-world validation. See <a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google&#39;s dataset guidance</a>.</li></ul><h2 id="delivery-gate-and-remaining-uncertainty">Delivery gate and remaining uncertainty<a class="header-anchor" href="#delivery-gate-and-remaining-uncertainty" aria-label="Link to this section">​</a></h2><p>On October 24, the November 10 beta is 17 days away and the November 21 pre-final is 28 days away. With October 31 onward protected for integration and testing, this is not a 17-day feature-development window.</p><table><thead><tr><th>Window</th><th>Proposed output</th></tr></thead><tbody><tr><td>Oct 24–25</td><td>Settle concept depth and AI requirement; Christian demonstrates one scenario → feedback → SQLite save → relaunch on a named phone. Record focused hours and remaining gaps.</td></tr><tr><td>Oct 26–30</td><td>Reuse the proven interaction for all three chapters; integrate approved copy, existing art and the smallest progress UI; freeze new mechanics.</td></tr><tr><td>Oct 31–Nov 6</td><td>Integration, phone tests, offline/recovery checks, content corrections and instructions.</td></tr><tr><td>Nov 7–9</td><td>Blocker fixes, regression, beta rehearsal and candidate freeze.</td></tr><tr><td><strong>Nov 10</strong></td><td><strong>Cryptita Plays community beta with the verified build.</strong></td></tr><tr><td>Nov 11–16</td><td>Retested fixes, actual findings, manuscript and evidence package.</td></tr><tr><td>Nov 17–20</td><td>Defense rehearsal and release freeze.</td></tr><tr><td><strong>Nov 21</strong></td><td><strong>Pre-final.</strong></td></tr></tbody></table><p>These are conditional planning gates, not confirmed capacity. There is no defensible new delivery promise until Christian supplies realistic focused hours and the first saved phone lesson. If that loop already works, most expansion becomes content and integration. If it does not, prioritize it before producing more scenes. If the core loop remains blocked at the content freeze, report the readiness gap and renegotiate the event deliverable; do not silently consume QA or drop AI from the stated educational goal.</p><p>If a working AI model is required, this minimum changes: use a separate timeboxed classifier spike with example-dependent predictions and a phone test. Remove other depth or adjust the commitment if it fails. Do not describe scripted branches as successful AI implementation.</p><p>A limited read-only inventory of <code>O:/Documents/Unity Projects/ChainyApp</code> found Unity <strong>6000.3.25f1</strong>, first-party movement/input/scene/menu infrastructure, and a <code>SQLiteTest</code> component. No APK/AAB was found in that inventory, and the folder did not provide a Git revision. This does not establish Christian&#39;s latest source state or device behavior; plugins and external work may contain additional functionality. No Unity build, play test or device test was run for this review.</p><h2 id="decisions-needed-before-adoption">Decisions needed before adoption<a class="header-anchor" href="#decisions-needed-before-adoption" aria-label="Link to this section">​</a></h2><ol><li>May the twelve existing concepts be delivered through shared guided scenarios, with their individual hands-on systems deferred?</li><li>Is a labelled scripted AI lesson acceptable, or does the adviser/owner require an actual offline model?</li><li>What works on Android now, and how many focused development hours can Christian realistically provide before November 10?</li></ol><p>Those questions have been raised with the owner. Until answered, this remains a concrete candidate rather than an approved scope revision. The requested source priority and the need to simplify are clear; the exact implementation and acceptance tradeoff remain open.</p><p>After a decision, Sean&#39;s documentation handoff should reconcile the canonical GDD, baseline, requirements, curriculum, technical addendum, UI flow and delivery plan. Sherwin owns that scope decision; Christian owns code/data/builds; Miguel owns UI implementation; Luis owns art. Use separate role handoff cards through the team board. This review does not create cards or change remote task status.</p><p>Later development should add one justified mechanic at a time to a tested build. Start with the largest remaining learning gap; do not assume the economy should be rebuilt merely because V2 proposed it. Preserve lesson identifiers and existing saves, but do not prebuild unused database tables or a general simulation framework now.</p></div>',1)])])}const u=t(r,[["render",o]]);export{m as __pageData,u as default};
